const bySlug = (items: any, slug: string) => {
  if (!items) return undefined;
  const list = Array.isArray(items) ? items : Object.values(items);
  return list.find((item: any) => item?.slug === slug);
};

export const getBlogBySlug = (slug: string) =>
  bySlug(Object.values(site.blogDetails), slug);
export const getServiceBySlug = (slug: string) =>
  bySlug(Object.values(site.serviceDetails), slug);
export const getJobBySlug = (slug: string) =>
  bySlug(site.jobDetails.jobs, slug) ||
  bySlug(site.jobDetails.jobDetailItems, slug);
export const getProjectBySlug = (slug: string) =>
  site.projectDetails.projects?.[slug] ||
  bySlug(site.projectDetails.projectDetailItems, slug);
export const getTeamMemberBySlug = (slug: string) =>
  site.teamDetails.members?.[slug] ||
  bySlug(site.teamDetails.teamDetailItems, slug);
